def word_frequency(text: str) -> dict[str, int]:
    if not text:
        return {}
    words = text.lower().split()
    word_counts = {}
    for word in words:
        cleaned_word = word.strip('.,!?')
        if cleaned_word:
            word_counts[cleaned_word] = word_counts.get(cleaned_word, 0) + 1
    return word_counts
